package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.PneumaticNetwork;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class PneumaticReceiverBlock extends PassiveDirectionalSignalBlock{public PneumaticReceiverBlock(Properties p){super(p);}@Override public MapCodec<PneumaticReceiverBlock> codec(){return RedstoneEngineering.PNEUMATIC_RECEIVER_CODEC.value();}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return Math.min(15,(PneumaticNetwork.pressure(l,inputPos(p,s))*15)/100);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Pneumatic receiver output="+outputValue(l,p,s)+"/15"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}